public function place(User $user, array $items): Order
{
    return DB::transaction(function () use ($user, $items) {
        $order = $user->orders()->create(['status' => 'pending', 'total' => 0]);
        $total = 0;

        foreach ($items as $item) {
            $product = Product::whereKey($item['product_id'])->lockForUpdate()->firstOrFail();

            if ($product->stock < $item['qty']) {
                throw new OutOfStock($product);   // rolls everything back
            }

            $product->decrement('stock', $item['qty']);
            $order->items()->create(['product_id' => $product->id, 'qty' => $item['qty'], 'price' => $product->price]);
            $total += $product->price * $item['qty'];
        }

        $order->update(['total' => $total]);
        OrderPlaced::dispatch($order);   // listeners should run after commit

        return $order;
    }, attempts: 3);
}

