class ImportProducts implements ShouldQueue
{
    use Queueable;

    public int $timeout = 1800;

    public function __construct(public Import $import) {}

    public function handle(): void
    {
        LazyCollection::make(function () {
            $handle = fopen(Storage::path($this->import->path), 'r');
            $header = fgetcsv($handle);
            while (($row = fgetcsv($handle)) !== false) {
                yield array_combine($header, $row);
            }
            fclose($handle);
        })
        ->chunk(1000)
        ->each(function (LazyCollection $chunk) {
            $rows = $chunk
                ->filter(fn ($row) => filled($row['sku']) && is_numeric($row['price']))
                ->map(fn ($row) => [
                    'sku'        => $row['sku'],
                    'name'       => $row['name'],
                    'price'      => (int) round($row['price'] * 100),
                    'updated_at' => now(),
                    'created_at' => now(),
                ])
                ->all();

            Product::upsert($rows, uniqueBy: ['sku'], update: ['name', 'price', 'updated_at']);

            $this->import->increment('processed', $chunk->count());
        });

        $this->import->update(['status' => 'finished']);
    }
}

